  'rond.naarHA.tekst': 'In de app van Home Assistant staat SunArc over het hele scherm. Met deze knop ga je naar Home Assistant, en met dezelfde knop weer terug. Liever met de balken van Home Assistant? Zet het uit bij Instellingen › Profiel › Dit scherm.',
  'rond.tandwiel.kop': 'Het tandwiel',
